  @override
  String get legalDataConsentRetentionBody =>
      'বেনামী প্ৰশিক্ষণ ডাটাছেটসমূহ মডেল বিকাশৰ বাবে প্ৰয়োজনীয় সময়ৰ বাবে ৰখা হয়, সাধাৰণতে সৃষ্টিৰ পৰা ২৪ মাহৰ। ফাইন-টিউনিং ডাটাছেটসমূহৰ বাবে ১২ মাহৰ পিছত স্পষ্ট পুনৰ সন্মতিৰ প্ৰয়োজন হয়। ভাড়াতীয়াৰ একাউণ্ট বন্ধ হোৱাৰ পিছত সেই ভাড়াতীয়াৰ বিষয়বস্তুৰ পৰা আহৰণ কৰা সকলো প্ৰশিক্ষণ তথ্য ৬০ দিনৰ ভিতৰত পাৰ্জ কৰা হয়।';

  @override
