  @override
  String get legalDisclaimerAINotLawyerBody =>
      'ছাতিৰ এআই ব্যৱস্থাসমূহ হৈছে সাধাৰণ আইনী কৰ্প’ৰাৰ ওপৰত প্ৰশিক্ষণপ্ৰাপ্ত বৃহৎ ভাষাৰ আৰ্হি। তেওঁলোকৰ হাতত প্ৰেকটিচিং চাৰ্টিফিকেট নাই, আদালতত হাজিৰ হ’ব নোৱাৰে, কোনো বাৰ এছ’চিয়েচন বা ল’ ছ’চাইটিৰ দ্বাৰা নিয়ন্ত্ৰিত নহয়, আৰু এজন অধিবক্তাৰ দৰে আপোনাৰ প্ৰতি কোনো যত্ন লোৱাৰ কৰ্তব্যৰ ঋণী নহয়। AI আউটপুটসমূহত: বাস্তৱিক ভুল বা ভ্ৰম থাকিব পাৰে; আপোনাৰ নিৰ্দিষ্ট তথ্যৰ সৈতে প্ৰাসংগিক বস্তুগত বিবেচনাসমূহ বাদ দিয়ক; সংশোধিত, বাতিল কৰা বা বাতিল কৰা বিধি বা গোচৰৰ উল্লেখ কৰা; শেহতীয়া আইনগত পৰিৱৰ্তনৰ হিচাপ নিদিয়া; আৰু জটিল বা অস্পষ্ট আইনী প্ৰশ্নৰ ভুল ব্যাখ্যা কৰা। আপুনি প্ৰতিটো AI আউটপুটক অনুসন্ধানৰ বাবে আৰম্ভণিৰ বিন্দু হিচাপে গণ্য কৰিব লাগিব, চূড়ান্ত উত্তৰ হিচাপে নহয়।';

  @override
  String get legalDisclaimerAINotLawyerHeading => '৩/ এআই কোনো উকীল নহয়';

  @override
  String get legalDisclaimerCitationBody =>
      'যেতিয়া Umbrella এ কোনো বিধি, নিয়ম, নিয়ম, বা ন্যায়িক সিদ্ধান্তৰ উদ্ধৃতি দিয়ে, আপুনি স্বতন্ত্ৰভাৱে পৰীক্ষা কৰিব লাগিব: (ক) উল্লেখ কৰা উৎসটো আছে নে নাই; (খ) উদ্ধৃতিটো সঠিক হোৱাটো (অংশ, উপধাৰা, আৰু বছৰ); (গ) যে উৎসটো বৰ্তমান বলবৎ হৈ আছে আৰু ইয়াক সংশোধন বা বাতিল কৰা হোৱা নাই; (ঘ) উদ্ধৃত পাঠটোৱে উৎসটোক সঠিকভাৱে প্ৰতিফলিত কৰে। AI উদ্ধৃতি ভুলসমূহ — নিৰ্মিত উদ্ধৃতিসমূহ অন্তৰ্ভুক্ত কৰি — সকলো বৰ্তমানৰ AI ব্যৱস্থাপ্ৰণালীৰ এটা জনা সীমাবদ্ধতা। আইনী কাৰ্য্যবিধি, পৰামৰ্শ বা ফাইলিঙত কেতিয়াও স্বতন্ত্ৰ পৰীক্ষণ অবিহনে উদ্ধৃতিৰ ওপৰত নিৰ্ভৰ নকৰিব।';

  @override
  String get legalDisclaimerCitationHeading => 'এআইৰ উদ্ধৃতিৰ নিয়ম';

  @override
  String get legalDisclaimerJurisdictionBody =>
      'ভাৰতঃ এআই বিশ্লেষণ কেন্দ্ৰীয় আইন, নিৰ্দিষ্ট ঠাইত ৰাজ্যিক আইন, আৰু প্ৰকাশিত ন্যায়িক সিদ্ধান্তৰ ওপৰত ভিত্তি কৰি কৰা হয়। ইয়াত জিলা আদালত পৰ্যায়ৰ প্ৰথা, স্থানীয় বাৰ কাষ্টম, বা অসংহিত পদ্ধতিগত নিয়মৰ হিচাপ দিয়া হোৱা নাই। আমেৰিকা যুক্তৰাষ্ট্ৰ: এআই বিশ্লেষণ ফেডাৰেল আইন আৰু নিৰ্বাচিত ৰাজ্যিক আইনৰ ওপৰত ভিত্তি কৰি কৰা হয়। আমেৰিকাৰ আইনী বিশ্লেষণ ৰাজ্য নিৰ্দিষ্ট অনুজ্ঞাপত্ৰপ্ৰাপ্ত অধিবক্তাৰ বিকল্প নহয়। পৰীক্ষিত অধিবক্তাৰ পৰ্যালোচনা অবিহনে অনুপ্ৰৱেশ, অপৰাধমূলক প্ৰতিৰক্ষা, বা কৰ বিষয়ৰ বাবে উপলব্ধ নহয়। কেনিয়া: বিশ্লেষণে কেনিয়াৰ বিধি, সহায়ক আইন, আৰু প্ৰকাশিত উচ্চ ন্যায়ালয় আৰু আপিল আদালতৰ সিদ্ধান্তৰ ওপৰত আধাৰিত। ইয়াত প্ৰথাগত আইন, দণ্ডাধীশ আদালতৰ ভিন্নতা বা অপ্ৰকাশিত ৰায়দানৰ হিচাপ দিয়া হোৱা নাই। যুক্তৰাজ্য: বিশ্লেষণে ইংৰাজী আৰু ৱেলছৰ আইন সামৰি লয়। স্কট আইন, উত্তৰ আইৰিছ আইন আৰু ডিভলভড বিষয়সমূহৰ মাজত যথেষ্ট পাৰ্থক্য থাকিব পাৰে; বিচাৰ ক্ষমতা-নিৰ্দিষ্ট পৰামৰ্শ বিচাৰিব।';

