  @override
  String get legalPrivacyLegalBasisBody =>
      'আমি আপোনাৰ অধিকাৰক্ষেত্ৰৰ ওপৰত নিৰ্ভৰ কৰি নিম্নলিখিত আইনী ভিত্তিৰ অধীনত ব্যক্তিগত তথ্য প্ৰক্ৰিয়াকৰণ কৰোঁ: (ক) চুক্তি — আপুনি চাইন আপ কৰা সেৱাসমূহ প্ৰদান কৰিবলৈ প্ৰয়োজনীয় প্ৰক্ৰিয়াকৰণ; (খ) বৈধ স্বাৰ্থ — জালিয়াতি প্ৰতিৰোধ, প্লেটফৰ্ম সুৰক্ষা, পণ্যৰ উন্নতি; (গ) সন্মতি — এআই প্ৰশিক্ষণ, বিপণন ইমেইল, কঠোৰ প্ৰয়োজনীয়তাৰ বাহিৰত কুকীজ; (ঘ) আইনী বাধ্যবাধকতা — প্ৰযোজ্য আইন মানি চলা। ভাৰতৰ বাবে প্ৰক্ৰিয়াকৰণ ডিজিটেল ব্যক্তিগত তথ্য সুৰক্ষা আইন ২০২৩ (ডিপিডিপি আইন)ৰ দ্বাৰা পৰিচালিত। ব্ৰিটেইন/ইউৰোপীয় ইউনিয়নৰ বাবে, প্ৰক্ৰিয়াকৰণ ব্ৰিটেইনৰ জিডিপিআৰ আৰু ইউৰোপীয় ইউনিয়নৰ জিডিপিআৰৰ সৈতে মিল খায়। কেনিয়াৰ বাবে, প্ৰক্ৰিয়াকৰণে তথ্য সুৰক্ষা আইন ২০১৯ মানি চলে। আমেৰিকাৰ ব্যৱহাৰকাৰীসকলৰ বাবে, আমি চিচিপিএ/চিপিআৰএকে ধৰি প্ৰযোজ্য ৰাজ্যিক গোপনীয়তা আইনসমূহ মানি চলে।';

