  @override
  String get legalTermsDefinitionsBody =>
      '\"প্লেটফৰ্ম\" ৰ অৰ্থ হৈছে umbrella.okaylegal.ai আৰু সকলো সংশ্লিষ্ট এপ্লিকেচন, API, আৰু সেৱাসমূহ। \"গ্ৰাহক ব্যৱহাৰকাৰী\" ৰ অৰ্থ হ\'ল নিজৰ আইনী পৰিস্থিতি বুজিবলৈ প্লেটফৰ্ম ব্যৱহাৰ কৰা এজন স্বাভাৱিক ব্যক্তি। \"উকীল ব্যৱহাৰকাৰী\" ৰ অৰ্থ হ\'ল উকীল অপাৰেটিং ছিষ্টেম বৈশিষ্ট্যসমূহ ব্যৱহাৰ কৰা এজন অনুজ্ঞাপত্ৰপ্ৰাপ্ত আইনী পেছাদাৰী। \"ভাড়াতীয়া\" বোলে ফাৰ্ম চাবস্ক্ৰিপচন থকা আইন সংস্থা বা সংস্থাক বুজায়। \"AI আউটপুট\" ৰ অৰ্থ হ\'ল Umbrella ৰ AI চিস্টেমসমূহে সৃষ্টি কৰা যিকোনো লিখনী, বিশ্লেষণ, খচৰা, বা পৰামৰ্শ। \"বিষয়\"ৰ অৰ্থ হ\'ল উকীল অ\'এছৰ জৰিয়তে পৰিচালিত আইনী গোচৰ বা লেনদেন। \"ডিভিটেক ভেঞ্চাৰছ\" বা \"আমি\" বোলে প্লেটফৰ্মৰ অপাৰেটৰক বুজায়।';

