  @override
  String get legalTermsDisputeBody =>
      'ভাৰত ব্যৱহাৰকাৰীসকল: এই চৰ্তসমূহ ভাৰতৰ আইনসমূহৰ দ্বাৰা পৰিচালিত; বেংগালুৰুত বহি থকা সালিসী আৰু মিলন আইন ১৯৯৬ৰ অধীনত বাধ্যতামূলক সালিসীৰ দ্বাৰা বিবাদ সমাধান কৰা হ’ব। আমেৰিকা যুক্তৰাষ্ট্ৰৰ ব্যৱহাৰকাৰীসকল: বিবাদসমূহ ডেলাৱেৰত বহি থকা AAA বাণিজ্যিক সালিসী নিয়মৰ অধীনত বাধ্যতামূলক সালিসীৰ দ্বাৰা সমাধান কৰা হ\'ব; ক্লাছ একচন ৰেহাই প্ৰযোজ্য। কেনিয়া ব্যৱহাৰকাৰীসকল: এই চৰ্তসমূহ কেনিয়াৰ আইনসমূহৰ দ্বাৰা পৰিচালিত; নাইৰোবি চেণ্টাৰ ফৰ ইণ্টাৰনেশ্যনেল আৰ্বিট্ৰেচন (এনচিআইএ)ৰ নিয়মৰ অধীনত বিবাদ সমাধান কৰা হ’ব। যুক্তৰাজ্যৰ ব্যৱহাৰকাৰীসকল: এই চৰ্তসমূহ ইংৰাজী আইন অনুসৰি পৰিচালিত; বিবাদ ইংলেণ্ড আৰু ৱেলছৰ আদালতৰ একচেটিয়া অধিকাৰক্ষেত্ৰত দাখিল কৰা হ’ব। সকলো ক্ষেত্ৰতে কোনো যোগ্য আদালতৰ পৰা জৰুৰী নিষেধাজ্ঞামূলক সকাহ বিচৰাত একোৱেই বাধা নিদিয়ে।';

  @override
  String get legalTermsDisputeHeading => '১৮) বিবাদ নিষ্পত্তি আৰু শাসকীয় আইন';

  @override
  String get legalTermsIPContentBody =>
      'আপুনি প্লেটফৰ্মত জমা দিয়া সকলো বিষয়বস্তুৰ মালিকীস্বত্ব ৰক্ষা কৰে। বিষয়বস্তু জমা দি আপুনি DVTech Ventures-ক কেৱল সেৱাসমূহ প্ৰদান কৰিবলৈ আপোনাৰ বিষয়বস্তু প্ৰক্ৰিয়াকৰণ, সংৰক্ষণ আৰু প্ৰদৰ্শন কৰিবলৈ এটা বিশ্বব্যাপী, ৰয়েল্টি-ফ্ৰী, অ-একচেটিয়া অনুজ্ঞাপত্ৰ প্ৰদান কৰে৷ এই অনুজ্ঞাপত্ৰ AI প্ৰশিক্ষণলৈ সম্প্ৰসাৰিত নহয় যেতিয়ালৈকে আপুনি তথ্য আৰু AI সন্মতি নীতিৰ অধীনত বিকল্প গ্ৰহণ নকৰে।';

