  @override
  String get legalTermsIPPlatformBody =>
      'ডিভিটেক ভেঞ্চাৰছৰ আমব্ৰেলা প্লেটফৰ্ম, ব্ৰেণ্ড, অন্তৰ্নিহিত এআই মডেল, আৰু প্ৰযুক্তিৰ সকলো অধিকাৰ আছে। আপোনাৰ স্বাক্ষৰণৰ সময়ৰ বাবে প্লেটফৰ্ম ব্যৱহাৰ কৰিবলৈ আপুনি এটা সীমিত, অ-একচেটিয়া, অ-হস্তান্তৰযোগ্য অনুজ্ঞাপত্ৰ প্ৰদান কৰা হৈছে।';

  @override
  String get legalTermsIndemnityBody =>
      'আপুনি DVTech Ventures আৰু ইয়াৰ বিষয়া, পৰিচালক, কৰ্মচাৰী, আৰু এজেণ্টসকলক যিকোনো দাবী, ক্ষতিপূৰণ, লোকচান, আৰু খৰচ (যুক্তিসংগত আইনী মাচুলকে ধৰি)ৰ পৰা আৰু বিৰুদ্ধে ক্ষতিপূৰণ দিবলৈ, ৰক্ষা কৰিবলৈ আৰু ধৰি ৰাখিবলৈ সন্মত হৈছে: (ক) এই চৰ্তসমূহ উলংঘা কৰি আপোনাৰ প্লেটফৰ্মৰ ব্যৱহাৰ; (খ) আপোনাৰ যিকোনো প্ৰযোজ্য আইন উলংঘা; (গ) আপুনি দাখিল কৰা বিষয়বস্তু যিয়ে তৃতীয় পক্ষৰ অধিকাৰ উলংঘা কৰে; (ঘ) আপুনি প্লেটফৰ্ম ব্যৱহাৰ কৰি আপোনাৰ ক্লায়েণ্টসকলক প্ৰদান কৰা আইনী পৰামৰ্শ বা সেৱাসমূহ।';

