  @override
  String get legalTermsLawyerUsersBody =>
      'উকীল ব্যৱহাৰকাৰীসকল স্বতন্ত্ৰ অনুজ্ঞাপত্ৰপ্ৰাপ্ত পেছাদাৰী। উকীল অ\' এছ ব্যৱহাৰ কৰি, আপুনি নিশ্চিত কৰে যে আপুনি আপোনাৰ এলেকাত এটা বৈধ প্ৰেকটিচিং প্ৰমাণপত্ৰ আছে আৰু আপুনি প্ৰযোজ্য পেছাদাৰী আচৰণৰ নিয়ম আৰু বাৰ নিয়মসমূহ মানি চলি প্লেটফৰ্ম ব্যৱহাৰ কৰিব। আপুনি আপোনাৰ ক্লায়েণ্টসকলক প্ৰদান কৰা সকলো আইনী কাম আৰু পৰামৰ্শৰ মানদণ্ড আৰু বৈধতাৰ বাবে আপুনি একমাত্ৰ দায়বদ্ধ হৈ থাকিব। ছাতিসমূহে সঁজুলিসমূহ প্ৰদান কৰে — ই উকীল ব্যৱহাৰকাৰীসকলৰ পেছাদাৰী আচৰণৰ তত্বাৱধান বা নিশ্চয়তা নিদিয়ে।';

