      'আপুনি: (ক) কোনো উকীল, ন্যায়াধীশ বা চৰকাৰী বিষয়াৰ ৰূপ ল’ব নালাগে; (খ) অধিবক্তাৰ পৰ্যালোচনা অবিহনে তৃতীয় পক্ষক আনুষ্ঠানিক আইনী পৰামৰ্শ হিচাপে এআই আউটপুট ব্যৱহাৰ কৰা; (গ) অবৈধ, মানহানিকাৰক বা প্ৰৱঞ্চনামূলক বিষয়বস্তু দাখিল কৰা; (ঘ) অন্তৰ্নিহিত এআই মডেল বা প্ৰশিক্ষণ তথ্যসমূহ ৰিভাৰ্ছ-ইঞ্জিনিয়াৰিং, স্ক্ৰেপ বা উলিয়াবলৈ চেষ্টা কৰা; (ঙ) লিখিত সন্মতি অবিহনে প্লেটফৰ্মত পুনৰ বিক্ৰী বা উপ-লাইচেন্স প্ৰৱেশ; (চ) তথ্য সুৰক্ষা, গ্ৰাহক সুৰক্ষা, আৰু আইনী বৃত্তিৰ নিয়মকে ধৰি প্ৰযোজ্য আইন উলংঘা কৰা যিকোনো ধৰণে প্লেটফৰ্ম ব্যৱহাৰ কৰা; (ছ) তৃতীয় পক্ষৰ বৌদ্ধিক সম্পত্তিৰ অধিকাৰ উলংঘা কৰা বিষয়বস্তু দাখিল কৰা।';

