  @override
  String get legalTermsRefundBody =>
      'আপুনি একাউণ্ট ছেটিংছৰ পৰা যিকোনো সময়তে আপোনাৰ স্বাক্ষৰণ বাতিল কৰিব পাৰে। বাতিল বৰ্তমানৰ বিলিং সময়ৰ শেষত কাৰ্যকৰী হয়; অব্যৱহৃত সময়ৰ বাবে কোনো আংশিক ধন ঘূৰাই দিয়া নহয়। যদি আপুনি বিশ্বাস কৰে যে আপুনি ভুলকৈ চাৰ্জ লোৱা হৈছে, চাৰ্জৰ ৩০ দিনৰ ভিতৰত support@odaflow.com ৰ সৈতে যোগাযোগ কৰক। আমি পৰ্যালোচনা কৰিম আৰু যদি প্ৰয়োজন হয়, আমাৰ বিবেচনা অনুসৰি প্ৰ\'-ৰাটা ৰিফাণ্ড জাৰি কৰিম।';

