  @override
  String get legalTermsSubscriptionBody =>
      'পেইড প্লেনসমূহ মাহেকীয়া বা বাৰ্ষিক চক্ৰত আগতীয়াকৈ বিল কৰা হয়। চেকআউটৰ সময়ত মূল্যসমূহ আপোনাৰ স্থানীয় মুদ্ৰাত প্ৰদৰ্শিত হয় আৰু প্ৰযোজ্য কৰ অন্তৰ্ভুক্ত হ\'ব পাৰে। আপুনি নবীকৰণৰ তাৰিখৰ আগতে বাতিল নকৰালৈকে প্ৰতিটো বিলিং সময়ৰ শেষত চাবস্ক্ৰিপচনসমূহ স্বয়ংক্ৰিয়ভাৱে নবীকৰণ কৰা হয়। ধন পৰিশোধ নকৰাৰ ফলত প্ৰৱেশ স্থগিত বা বন্ধ হ\'ব পাৰে।';

